def solve_langford(n):
    from pysat.solvers import Glucose3

    # Variables: x_{v, i} means value v starts at position i
    # v in 1..n
    # i in 0..2n - v - 2

    var_map = {}
    var_counter = 1

    # For each v, list of possible start positions
    v_starts = {v: [] for v in range(1, n + 1)}

    for v in range(1, n + 1):
        for i in range(2 * n - v - 1):
            var_map[(v, i)] = var_counter
            v_starts[v].append(var_counter)
            var_counter += 1

    solver = Glucose3()

    # 1. Each value v is placed exactly once
    for v in range(1, n + 1):
        starts = v_starts[v]
        solver.add_clause(starts)
        for i in range(len(starts)):
            for j in range(i + 1, len(starts)):
                solver.add_clause([-starts[i], -starts[j]])

    # 2. Each position is covered exactly once
    pos_covers = {p: [] for p in range(2 * n)}
    for v in range(1, n + 1):
        for i in range(2 * n - v - 1):
            var = var_map[(v, i)]
            pos_covers[i].append(var)
            pos_covers[i + v + 1].append(var)

    for p in range(2 * n):
        covers = pos_covers[p]
        solver.add_clause(covers)
        for i in range(len(covers)):
            for j in range(i + 1, len(covers)):
                solver.add_clause([-covers[i], -covers[j]])

    # Symmetry breaking: the first number is placed in the first half
    # Actually, we can just fix the first position to be covered by something,
    # or just let the solver do it.

    if solver.solve():
        model = solver.get_model()
        seq = [0] * (2 * n)
        for v in range(1, n + 1):
            for i in range(2 * n - v - 1):
                if model[var_map[(v, i)] - 1] > 0:
                    seq[i] = v
                    seq[i + v + 1] = v
        return seq
    else:
        return None

print(solve_langford(36))
